#!/usr/bin/env node
/**
 * Walks dist/ (post `npm run build` + prerender) and emits src/prerendered.ts
 * mapping each route path -> the prerendered HTML string. Also snapshots
 * public/route-manifest.json into src/route-manifest.ts so the Worker
 * bundles it at deploy time, and validates LEGACY_REDIRECTS values.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(__dirname, "../..");
const DIST = path.resolve(REPO_ROOT, "dist");
const OUT = path.resolve(__dirname, "src/prerendered.ts");
const MANIFEST_SRC = path.resolve(REPO_ROOT, "public/route-manifest.json");
const MANIFEST_OUT = path.resolve(__dirname, "src/route-manifest.ts");
const LEGACY_SRC = path.resolve(__dirname, "src/legacy-redirects.json");

if (!fs.existsSync(DIST)) {
  console.error(`[build-bundle] dist/ missing — run \`npm run build\` first.`);
  process.exit(1);
}
if (!fs.existsSync(MANIFEST_SRC)) {
  console.error(`[build-bundle] public/route-manifest.json missing — run \`npm run build\` first.`);
  process.exit(1);
}

/** Recursively find every index.html under dist/, return route path. */
function walk(dir, acc = []) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      walk(full, acc);
    } else if (entry.isFile() && entry.name === "index.html") {
      const rel = path.relative(DIST, path.dirname(full));
      // dist/index.html -> "/", dist/en/index.html -> "/en", etc.
      const route = rel === "" ? "/" : "/" + rel.split(path.sep).join("/");
      acc.push({ route, file: full });
    }
  }
  return acc;
}

const entries = walk(DIST)
  // Skip the root SPA shell — the Worker should NOT serve a prerendered
  // homepage that lacks per-route metadata (root "/" redirects to "/en"
  // anyway via React Router).
  .filter(({ route }) => route !== "/")
  .sort((a, b) => a.route.localeCompare(b.route));

const lines = entries.map(({ route, file }) => {
  const html = fs.readFileSync(file, "utf-8");
  return `  ${JSON.stringify(route)}: ${JSON.stringify(html)}`;
});

const out = `// AUTO-GENERATED by build-bundle.mjs — DO NOT EDIT.
// Regenerate via \`npm run build\` inside workers/route-server/.
export const PRERENDERED: Record<string, string> = {
${lines.join(",\n")}
};
`;

fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, out);

const totalKb = Math.round(Buffer.byteLength(out, "utf8") / 1024);
console.log(`[build-bundle] wrote ${entries.length} routes -> ${OUT} (${totalKb} KB)`);
for (const { route } of entries) console.log(`  • ${route}`);

// ---------------------------------------------------------------------------
// Snapshot public/route-manifest.json into src/route-manifest.ts so the
// Worker bundles it at deploy time. The manifest is the source of truth for
// which URLs return HTTP 200; the Worker must NOT diverge from it.
// ---------------------------------------------------------------------------
const manifest = JSON.parse(fs.readFileSync(MANIFEST_SRC, "utf-8"));
const manifestOut = `// AUTO-GENERATED by build-bundle.mjs — DO NOT EDIT.
// Snapshot of public/route-manifest.json produced by scripts/generate-route-manifest.mjs.
export const ROUTE_MANIFEST = ${JSON.stringify(manifest, null, 2)} as const;
`;
fs.writeFileSync(MANIFEST_OUT, manifestOut);
console.log(
  `[build-bundle] wrote route manifest -> ${MANIFEST_OUT} (${manifest.allRoutes.length} routes, ${
    Object.values(manifest.blogSlugs).reduce((n, s) => n + s.length, 0)
  } blog slugs)`,
);

// ---------------------------------------------------------------------------
// Validate LEGACY_REDIRECTS: every value MUST resolve to a real 200 route.
// Sources of truth: PRERENDERED keys, route-manifest.allRoutes, and the
// remaining narrow DYNAMIC_ROUTES patterns kept in src/index.ts. A 301 that
// lands on a hard 404 is strictly worse than the current soft-404 behaviour.
// ---------------------------------------------------------------------------
const LEGACY = JSON.parse(fs.readFileSync(LEGACY_SRC, "utf-8"));
const DYNAMIC_PATTERNS = [
  /^\/en\/(size|bridge|temple)\/\d{2,3}mm$/,
  /^\/en\/xxl(\/[a-z0-9-]+)?$/,
  /^\/en\/compare(\/[a-z0-9-]+-alternative)?$/,
  /^\/en\/collections\/[a-z0-9-]+$/,
  /^\/en\/account(\/.*)?$/,
];
const prerenderedKeys = new Set(entries.map((e) => e.route));
const manifestKeys = new Set(manifest.allRoutes);
const blogRoutes = new Set(
  Object.entries(manifest.blogSlugs).flatMap(([locale, slugs]) =>
    slugs.map((s) => `/${locale}/blog/${s}`),
  ),
);
function isKnownAtBuild(p) {
  return (
    prerenderedKeys.has(p) ||
    manifestKeys.has(p) ||
    blogRoutes.has(p) ||
    DYNAMIC_PATTERNS.some((re) => re.test(p))
  );
}
const badTargets = Object.entries(LEGACY).filter(([, dst]) => !isKnownAtBuild(dst));
if (badTargets.length) {
  console.error("[build-bundle] LEGACY_REDIRECTS points at unknown routes:");
  for (const [src, dst] of badTargets) console.error(`  ${src} -> ${dst}`);
  process.exit(1);
}
console.log(`[build-bundle] validated ${Object.keys(LEGACY).length} legacy redirects`);

// ---------------------------------------------------------------------------
// Safety check: every blog URL in the sitemap AND every prerendered blog
// path must resolve through the new isKnownRoute() (i.e. be in BLOG_ROUTES,
// prerendered, or extra routes). Anything missing would go offline.
// ---------------------------------------------------------------------------
const sitemapPath = path.resolve(REPO_ROOT, "public/sitemap.xml");
if (fs.existsSync(sitemapPath)) {
  const xml = fs.readFileSync(sitemapPath, "utf-8");
  const sitemapBlog = [...xml.matchAll(/<loc>([^<]+)<\/loc>/g)]
    .map((m) => m[1].replace("https://woolet.co", ""))
    .filter((p) => /\/blog\//.test(p));
  const missing = sitemapBlog.filter((p) => !blogRoutes.has(p) && !prerenderedKeys.has(p));
  if (missing.length) {
    console.error("[build-bundle] sitemap blog URLs missing from manifest:");
    for (const p of missing) console.error(`  ${p}`);
    process.exit(1);
  }
  console.log(`[build-bundle] sitemap blog parity OK (${sitemapBlog.length} URLs)`);
}
// /blog/category/* and /blog/tag/* are taxonomy pages, not posts — they are
// prerendered but never appear in manifest.blogSlugs. Excluding them keeps the
// guard meaningful for actual posts.
const BLOG_TAXONOMY = /\/blog\/(category|tag)\//;
const prerenderedBlog = [...prerenderedKeys].filter(
  (p) => /\/blog\//.test(p) && !BLOG_TAXONOMY.test(p),
);
const missingPre = prerenderedBlog.filter((p) => !blogRoutes.has(p));
if (missingPre.length) {
  console.error("[build-bundle] prerendered blog paths missing from manifest:");
  for (const p of missingPre) console.error(`  ${p}`);
  process.exit(1);
}
console.log(
  `[build-bundle] prerendered blog parity OK (${prerenderedBlog.length} prerendered, ${blogRoutes.size} in manifest)`,
);

